<?= $this->extend('layouts/staff') ?><?= $this->section('content') ?>
<?php
use App\Libraries\DisplayDate;
$peso = static fn($value) => ((float) $value < 0 ? '−' : '') . '₱' . number_format(abs((float) $value), 2);
$cents = static fn($value) => (int) round((float) $value * 100);
$limit = 200;
$drawerUsed = count(array_filter($drawers, static fn($d) => !empty($d['active_shift_id'])));
$awaiting = array_values(array_filter($shifts, static fn($row) => $row['status'] === 'closed' && !$row['reviewed_at']));
$varianceCents = array_sum(array_map(static fn($row) => $cents($row['cash_difference']), $awaiting));
$offCount = count(array_filter($awaiting, static fn($row) => $cents($row['cash_difference']) !== 0));
$moreShifts = count($shifts) === $limit; $moreEvents = count($exceptions) === $limit;
$awaitingNote = $onlyPending ? ($moreShifts ? 'More pages of closings are waiting' : 'Every closing waiting for a review') : 'Among the latest ' . count($shifts) . ' shifts';
$kpis = [
    ['Drawers in use', $drawerUsed . ' of ' . count($drawers), 'Shared branch drawers', 'primary', '<rect x="3" y="10" width="18" height="11" rx="2"/><path d="M7 10V3h10v7M3 15h18"/>'],
    ['Closings awaiting review', count($awaiting) . ($onlyPending && $moreShifts ? '+' : ''), $awaitingNote, count($awaiting) ? 'warn' : 'ok', '<path d="M9 12l2 2 4-4"/><circle cx="12" cy="12" r="9"/>'],
    ['Movements to review', count($exceptions) . ($moreEvents ? '+' : ''), 'Refunds, exchanges, corrections and cash moves', $exceptions ? 'warn' : 'ok', '<path d="M4 7h14l-3-3M20 17H6l3 3"/>'],
    ['Unreviewed over / short', ($varianceCents > 0 ? '+' : '') . $peso($varianceCents / 100), $offCount ? $offCount . ' closing(s) with a difference' : 'No differences in awaiting closings', $varianceCents < 0 ? 'danger' : ($varianceCents > 0 ? 'warn' : 'ok'), '<path d="M12 3v18M17 7H9.5a3.5 3.5 0 000 7h5a3.5 3.5 0 010 7H6"/>'],
];
$eventTone = ['refund' => 'bad', 'exchange' => 'info', 'adjustment' => 'warn', 'cash_in' => 'ok', 'cash_out' => 'warn'];
?>
<link rel="stylesheet" href="<?= base_url('assets/css/cashier-workspace.css') ?>?v=20261023">
<div class="cashier-workspace"><div class="cw-heading"><div><span class="cw-eyebrow">Administration</span><h1>Cashier Shifts</h1><p>Review branch drawers, closing differences and exceptional transactions.</p></div><a class="btn secondary" href="<?= site_url('cashier/my-day') ?>">My Day</a></div>
<?= view('cashier/workspace/_messages') ?>

<div class="cw-stats cw-stats-4" aria-label="Shift review summary">
<?php foreach ($kpis as [$label, $value, $help, $tone, $icon]): ?><div class="cw-stat" data-tone="<?= $tone ?>"><div class="cw-stat-top"><span class="cw-stat-icon" aria-hidden="true"><svg width="16" height="16" fill="none" viewBox="0 0 24 24" stroke="currentColor" stroke-width="2" stroke-linecap="round" stroke-linejoin="round"><?= $icon ?></svg></span><span class="cw-stat-label"><?= esc($label) ?></span></div><strong class="<?= $tone === 'danger' ? 'is-neg' : '' ?>"><?= esc($value) ?></strong><small><?= esc($help) ?></small></div><?php endforeach; ?>
</div>

<section class="cw-card"><div class="cw-card-head"><h2>Shared branch drawers</h2><p>One drawer per branch. Close an open shift before disabling its drawer.</p></div>
<?php if ($drawers): ?><div class="cw-drawers"><?php foreach ($drawers as $drawer): ?>
    <?php if ($drawer['status'] !== 'active'): $state = 'is-off'; $badge = ['', 'Disabled']; elseif ($drawer['active_shift_id']): $state = 'is-busy'; $badge = ['is-ok', 'In use']; elseif ($drawer['handover_status'] === 'pending'): $state = 'is-wait'; $badge = ['is-warn', 'Handover pending']; else: $state = 'is-free'; $badge = ['is-info', 'Available']; endif; ?>
    <article class="cw-drawer <?= $state ?>"><header><div><strong><?= esc($drawer['branch_name']) ?></strong><small><?= esc($drawer['drawer_name']) ?></small></div><span class="cw-badge <?= $badge[0] ?>"><?= $badge[1] ?></span></header>
        <p><?php if ($drawer['active_shift_id']): ?><a href="<?= site_url('cashier/shifts/'.$drawer['active_shift_id']) ?>"><?= esc($drawer['current_cashier']) ?> · shift #<?= (int)$drawer['active_shift_id'] ?></a>
        <?php elseif ($drawer['status'] === 'active' && $drawer['handover_status'] === 'pending'): ?><a href="<?= site_url('cashier/shifts/'.$drawer['last_shift_id']) ?>">Waiting for <?= esc($drawer['handover_name']) ?></a>
        <?php elseif ($drawer['status'] !== 'active'): ?>Enable it below to let cashiers start shifts.
        <?php else: ?>No cashier is using this drawer.<?php endif; ?></p></article>
<?php endforeach; ?></div><?php else: ?><p class="cw-empty">No branch drawers configured. Choose a branch below to create its drawer.</p><?php endif; ?>
<div class="cw-drawer-form"><p>Create or enable a drawer for a branch, or disable one that is not in use.</p><form class="cw-form-inline" method="post" action="<?= site_url('admin/cashier-shifts/drawer') ?>"><?= csrf_field() ?><select class="input" name="branch_id" aria-label="Branch" required><?php foreach ($branches as $branch): ?><option value="<?= (int)$branch['id'] ?>"><?= esc($branch['branch_name']) ?></option><?php endforeach; ?></select><select class="input" name="drawer_status" aria-label="Drawer availability"><option value="active">Enable / create drawer</option><option value="inactive">Disable drawer</option></select><button class="btn secondary">Update drawer</button></form></div></section>

<section class="cw-card"><div class="cw-card-head has-side"><div><h2>Shifts and cash differences</h2><p>Latest <?= $limit ?> shifts per page. Select Review to inspect a shift and record its closing review.</p></div>
    <div class="cw-range" role="group" aria-label="Shift filter"><a class="cw-chip<?= !$onlyPending ? ' is-active' : '' ?>" <?= !$onlyPending ? 'aria-current="true"' : '' ?> href="<?= site_url('admin/cashier-shifts') ?>">Latest shifts</a><a class="cw-chip<?= $onlyPending ? ' is-active' : '' ?>" <?= $onlyPending ? 'aria-current="true"' : '' ?> href="<?= site_url('admin/cashier-shifts?pending=1') ?>">Awaiting review</a></div></div>
<div class="cw-table-scroll table-wrap"><table class="cw-table cw-table-wide js-datatable" data-dt-order="0:desc" data-dt-empty="<?= $onlyPending ? 'No closings are waiting for review.' : 'No shifts yet.' ?>" aria-label="Shift reviews"><thead><tr><th>Shift</th><th>Cashier / branch</th><th>Opened / closed</th><th>Status</th><th class="money" data-dt-filter="off">Expected / counted</th><th class="money" data-dt-filter="off">Over / short</th><th>Review status</th><th class="no-sort">Actions</th></tr></thead><tbody>
<?php foreach ($shifts as $row): ?><?php $needsReview = $row['status'] === 'closed' && !$row['reviewed_at']; $diff = $row['cash_difference'] === null ? null : round((float) $row['cash_difference'], 2); ?><tr<?= $needsReview ? ' class="cw-row-attn"' : '' ?>><td data-order="<?= (int)$row['id'] ?>">#<?= (int)$row['id'] ?></td><td><?= esc($row['full_name']) ?><small><?= esc($row['branch_name']) ?></small></td><td><?= esc(DisplayDate::dateTime($row['opened_at'])) ?><small><?= $row['closed_at'] ? esc(DisplayDate::dateTime($row['closed_at'])) : 'Still open' ?></small></td><td><span class="cw-badge <?= $row['status'] === 'open' ? 'is-ok' : '' ?>"><?= esc(ucfirst($row['status'])) ?></span></td><td class="money" data-order="<?= $row['expected_cash'] === null ? '-1000000000000000' : esc($row['expected_cash'],'attr') ?>"><?= $row['expected_cash'] === null ? '—' : $peso($row['expected_cash']) ?><small><?= $row['counted_cash'] === null ? '—' : $peso($row['counted_cash']) ?></small></td><td class="money" data-order="<?= $diff === null ? '-1000000000000000' : esc((string) $diff,'attr') ?>"><?php if ($diff === null): ?>—<?php else: ?><span class="cw-diff <?= $diff < 0 ? 'is-short' : ($diff > 0 ? 'is-over' : 'is-even') ?>"><?= $peso($diff) ?></span><small><?= $diff < 0 ? 'Short' : ($diff > 0 ? 'Over' : 'Balanced') ?></small><?php endif; ?><?php if ((float)$row['opening_difference']!==0.0): ?><small>Opening: <?= $peso($row['opening_difference']) ?></small><?php endif; ?></td><td><?php if ($row['reviewed_at']): ?><span class="cw-badge is-ok">Reviewed</span><?php elseif ($row['status']==='closed'): ?><span class="cw-badge is-warn">Awaiting review</span><?php else: ?><span class="cw-badge is-info">In progress</span><?php endif; ?></td><td><a class="btn <?= $needsReview ? 'btn-primary' : 'secondary' ?> btn-sm" href="<?= site_url('cashier/shifts/'.$row['id']) ?>" aria-label="Review shift #<?= (int)$row['id'] ?>">Review</a></td></tr><?php endforeach; ?>
<?php if (!$shifts): ?><tr><td colspan="8" class="cw-empty"><?= $onlyPending ? 'No closings are waiting for review.' : 'No shifts yet.' ?></td></tr><?php endif; ?></tbody></table></div>
<?php if ($moreShifts): ?><div class="cw-card-foot"><span>Showing <?= count($shifts) ?> shifts.</span><a class="btn secondary btn-sm" href="<?= site_url('admin/cashier-shifts?'.http_build_query(['before_shift'=>end($shifts)['id'],'before_event'=>$beforeEvent,'pending'=>$onlyPending?'1':'0'])) ?>">Older shifts</a></div><?php endif; ?></section>

<section class="cw-card"><div class="cw-card-head"><h2>Movements awaiting review <?php if ($exceptions): ?><span class="cw-count is-warn"><?= count($exceptions) ?><?= $moreEvents ? '+' : '' ?></span><?php endif; ?></h2><p>Latest <?= $limit ?> unreviewed refunds, exchanges, corrections and cash movements. Review notes are saved with the administrator's name.</p></div><div class="cw-table-scroll table-wrap"><table class="cw-table cw-table-wide js-datatable" data-dt-empty="No movements awaiting review." aria-label="Exceptional movements"><thead><tr><th>When / cashier</th><th>Movement</th><th class="money">Amount</th><th>Reason / invoice</th><th class="no-sort">Manager review</th></tr></thead><tbody>
<?php foreach ($exceptions as $event): ?><?php $snapshot=json_decode($event['snapshot_json'] ?: '{}',true) ?: []; ?><tr><td><?= esc(DisplayDate::dateTime($event['created_at'])) ?><small><?= esc($event['full_name']) ?> · <?= esc($event['branch_name']) ?></small></td><td><span class="cw-badge is-<?= $eventTone[$event['event_type']] ?? 'muted' ?>"><?= esc(ucwords(str_replace('_',' ',$event['event_type']))) ?></span><small><a href="<?= site_url('cashier/shifts/'.$event['shift_id']) ?>">Shift #<?= (int)$event['shift_id'] ?></a> · <?= esc(strtoupper($event['payment_method'])) ?></small></td><td class="money<?= (float)$event['amount'] < 0 ? ' is-neg' : '' ?>"><?= $peso($event['amount']) ?></td><td><?= esc($event['reason']) ?><?php if ($event['sale_id']): ?><small><a href="<?= site_url('cashier/sales/view/'.$event['sale_id']) ?>"><?= esc($snapshot['invoice'] ?? 'View sale') ?></a></small><?php endif; ?></td><td><form class="cw-form-inline" method="post" action="<?= site_url('admin/cashier-shifts/review/event/'.$event['id']) ?>"><?= csrf_field() ?><input class="input" name="review_note" aria-label="Review note for movement <?= (int)$event['id'] ?>" minlength="3" maxlength="500" required placeholder="Review note"><button class="btn secondary btn-sm">Reviewed</button></form></td></tr><?php endforeach; ?>
<?php if (!$exceptions): ?><tr><td colspan="5" class="cw-empty">No movements awaiting review.</td></tr><?php endif; ?></tbody></table></div>
<?php if ($moreEvents): ?><div class="cw-card-foot"><span>Showing <?= count($exceptions) ?> movements.</span><a class="btn secondary btn-sm" href="<?= site_url('admin/cashier-shifts?'.http_build_query(['before_shift'=>$beforeShift,'before_event'=>end($exceptions)['id'],'pending'=>$onlyPending?'1':'0'])) ?>">Older movements awaiting review</a></div><?php endif; ?></section>
</div>
<?= $this->endSection() ?>
